Returns `true` when `node` is the last hard line break of its paragraph\n/// block, i.e. it has no following content sibling, or its immediate next\n/// sibling is empty (whitespace only) text. In that case the trailing\n/// two-space marker carries no meaning and should be removed.\nfn is_last_hard_line(node: &MdHardLine) -> bool {\n    match node.syntax().next_sibling() {\n        None => true,\n        Some(sibling) => {\n            sibling.kind() == MarkdownSyntaxKind::MD_TEXTUAL\n                && sibling.text_trimmed().to_string().trim().is_empty()\n        }\n    }\n}\n\npub(crate) struct FormatMdFormatHardLineOptions {\n    pub(crate) print_mode: TextPrintMode,\n}\n\nimpl FormatRuleWithOptions<MdHardLine> for FormatMdHardLine {\n    type Options = FormatMdFormatHardLineOptions;\n\n    fn with_options(mut self, options: Self::Options) -> Self {\n        self.print_mode = options.print_mode;\n        self\n    }\n}\n", "numLines": 77, "startLine": 1, "totalLines": 77}}
